1	// A compact, chat-owned account of the setup: what the chat asked for, the
2	// selected presets, how the agent means to print (its plan's headline), and
3	// the estimates. Native code supplies the facts; this page presents them.
4	// The settings that differ from the presets are on the setup page.
5	
6	import { ReactNode, useState } from 'react';
7	import { ChangeInfo, SliceEstimateInfo, WorkspaceContext } from '../bridge/protocol';
8	
9	export interface SetupCardProps {
10	  context: WorkspaceContext | null;
11	  working?: boolean;
12	  historical?: boolean;
13	  savedAt?: string;
14	  agentAvailable?: boolean;
15	  changes?: ChangeInfo[];
16	  now?: number;
17	  estimateBefore?: SliceEstimateInfo | null;
18	  sent?: { at: string; printer: string };
19	  attention?: Finding[];
20	  onCompute?: () => void;
21	  onUndo?: (changeSeq: number) => void;
22	  onViewSetup?: () => void;
23	}
