25	export function formatPrintTime(seconds: number): string {
26	  const minutes = Math.round(seconds / 60);
27	  if (minutes < 60) return `~${minutes} min`;
28	  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
29	}
30	
31	export function formatGrams(grams: number): string {
32	  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
33	}
34	
35	export function formatCost(cost: number, currency: string): string {
36	  if (currency) {
37	    try {
38	      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
39	    } catch {
40	      // An unknown regional code does not make the native amount disappear.
41	    }
42	  }
43	  return `cost ${cost.toFixed(2)}`;
44	}
45	
46	export function formatMoment(value: string | undefined): string {
47	  if (!value) return '';
48	  const date = new Date(value);
49	  if (Number.isNaN(date.getTime())) return value;
50	  return date.toLocaleString(undefined, {
51	    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false,
52	  });
53	}
54	
55	export const RECENT_CHANGE_MS = 60000;
56	
57	export interface EstimateView {
58	  heading: string;
59	  metrics: { icon: string; text: string }[];
60	  cost: string;
61	  plate: string;
62	  description: string;
63	  status: 'current' | 'recomputing' | 'stale' | 'none';
64	  sliced: boolean;
65	}
66	
67	export function estimateView(context: WorkspaceContext): EstimateView {
68	  const plate = context.plates.find((item) => item.active);
69	  const view: EstimateView = {
70	    heading: '', metrics: [], cost: '', plate: plate?.name ?? '', description: '', status: 'none', sliced: !!plate?.sliced,
71	  };
72	  if (!plate) return { ...view, description: 'Estimate unavailable' };
73	  const estimate = plate.estimate;
74	  const scoped = (text: string) => plate.name ? `${text} · ${plate.name}` : text;
75	  const metrics: EstimateView['metrics'] = [];
76	  if (estimate && (estimate.timeAvailable ?? estimate.printTimeSeconds > 0))
77	    metrics.push({ icon: 'clock', text: formatPrintTime(estimate.printTimeSeconds) });
78	  if (estimate && (estimate.materialAvailable ?? estimate.materialGrams > 0))
79	    metrics.push({ icon: 'package', text: formatGrams(estimate.materialGrams) });
80	  if (plate.estimateStatus === 'recomputing')
81	    return { ...view, status: 'recomputing', heading: 'Time & material estimates recomputing…',
82	      description: scoped('Settings confirmed') };
83	  if (metrics.length === 0)
84	    return { ...view, description: scoped(plate.sliced ? 'Estimate unavailable' : 'Not sliced yet · estimates unavailable') };
85	  const cost = estimate && estimate.materialCost !== null && estimate.materialCost >= 0.005
86	    ? formatCost(estimate.materialCost, context.currency) : '';
87	  if (plate.estimateStatus === 'stale')
88	    return { ...view, status: 'stale', heading: 'Previous estimates · not current', metrics, cost };
89	  return { ...view, status: 'current', metrics, cost };
90	}
