92	export interface Finding { title: string; detail?: string; facts?: string[]; }
93	
94	export function deterministicAttention(context: WorkspaceContext): Finding[] {
95	  const review = context.printerReview;
96	  if (!review) return [];
97	  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
98	  const noun: Record<string, string> = { filament: 'material', nozzle: 'nozzle', model: 'printer', plate: 'build plate' };
99	  const when = formatMoment(review.observed?.observedAt);
100	  return [...review.mismatches].sort((a, b) => (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
101	    const thing = noun[mismatch.what] ?? 'printer setup';
102	    if (mismatch.source === 'device') {
103	      if (!when) return [];
104	      const facts = [`Setup: ${mismatch.configured}`, `Printer last reported: ${mismatch.observed}`, `Reported ${when}`];
105	      if (review.observed?.connection) facts.push(`Printer is ${review.observed.connection} now`);
106	      return [{ title: `Last reported ${thing} differs`,
107	        detail: `Setup uses ${mismatch.configured}. Printer last reported ${mismatch.observed}.`, facts }];
108	    }
109	    return [{ title: `Confirmed ${thing} differs`,
110	      detail: `Setup uses ${mismatch.configured}. You confirmed ${mismatch.observed}.`,
111	      facts: [`Setup: ${mismatch.configured}`, `You confirmed: ${mismatch.observed}`] }];
112	  });
113	}
