115	export function recentAgentChange(changes: ChangeInfo[] | undefined, now: number): ChangeInfo[] {
116	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
117	  const last = log.at(-1);
118	  if (!last || last.actor !== 'agent' || (last.kind !== 'setting' && last.kind !== 'step')) return [];
119	  const made = Date.parse(last.createdAt);
120	  if (!Number.isFinite(made) || now - made >= RECENT_CHANGE_MS || now < made) return [];
121	  let start = log.length - 1;
122	  while (start > 0 && log[start - 1].actor === 'agent' && log[start - 1].afterId === last.afterId &&
123	    (log[start - 1].kind === 'setting' || log[start - 1].kind === 'step')) start -= 1;
124	  return log.slice(start);
125	}
126	
127	export function handEdits(changes: ChangeInfo[] | undefined): ChangeInfo[] {
128	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
129	  let start = log.length;
130	  while (start > 0 && log[start - 1].actor === 'person' && log[start - 1].kind !== 'restore') start -= 1;
131	  const net = new Map<string, ChangeInfo>();
132	  for (const change of log.slice(start))
133	    if (change.kind === 'setting') net.set(change.key || change.label, change);
134	  return [...net.values()];
135	}
