137	function estimatePair(estimate: SliceEstimateInfo): string {
138	  return `${formatPrintTime(estimate.printTimeSeconds)} / ${formatGrams(estimate.materialGrams)}`;
139	}
140	
141	function plural(count: number, one: string, many: string): string {
142	  return `${count} ${count === 1 ? one : many}`;
143	}
