150	export function presetsLine(context: WorkspaceContext, title: string): string {
151	  const process = context.printer.process.trim();
152	  if (!process) return '';
153	  const filaments = context.setupIdentity?.filaments ?? [];
154	  const first = (filaments[0]?.preset || context.printer.filament).trim();
155	  const filament = first ? `${shortPreset(first)}${filaments.length > 1 ? ` +${filaments.length - 1}` : ''}` : '';
156	  const parts = title === process ? [filament] : [shortPreset(process), filament];
157	  return parts.filter(Boolean).join(' · ');
158	}
