160	// Objects that print with settings of their own. The headline cannot say so,
161	// and nothing else on the card does.
162	export function overrideObjectCount(context: WorkspaceContext): number {
163	  return new Set((context.appliedSetup?.localOverrides ?? [])
164	    .map((local) => local.object).filter((object): object is number => object !== undefined)).size;
165	}
