167	export interface SetupPresentationOptions {
168	  historical?: boolean;
169	  working?: boolean;
170	  agentAvailable?: boolean;
171	  changes?: ChangeInfo[];
172	  now?: number;
173	  sent?: { at: string; printer: string };
174	  savedAt?: string;
175	}
