177	// What the card and the setup page both say about themselves: their label,
178	// their one state, their title. Conversation status outranks live activity: a
179	// saved card is never working, whatever the active chat happens to be doing.
180	export function setupPresentation(context: WorkspaceContext, options: SetupPresentationOptions = {}) {
181	  const historical = !!options.historical;
182	  const working = !!options.working && !historical;
183	  const estimate = estimateView(context);
184	  const intent = context.setupIntent.trim();
185	  const title = intent || context.printer.process.trim();
186	  // Nothing vouches for this setup but the preset the person picked: no agent
187	  // is configured, or the host read no settings to compare with it.
188	  const noAgent = !historical && options.agentAvailable === false;
189	  if (noAgent || (!historical && !context.appliedSetup && !intent))
190	    return { label: 'Preset fallback', state: noAgent ? 'No agent' : null as ReactNode, title: context.printer.process.trim(),
191	      estimate, justChanged: [], edited: [], editedByYou: false, outOfDate: false, live: true, fallback: true, noAgent };
192	  const justChanged = historical ? [] : recentAgentChange(options.changes, options.now ?? Date.now());
193	  const edited = historical || working || justChanged.length > 0 ? [] : handEdits(options.changes);
194	  // "Edited by you" needs a setup the agent had a hand in; without one a
195	  // hand edit is simply how the project was made.
196	  const agentManaged = !!intent || (options.changes ?? []).some((change) => change.actor === 'agent');
197	  const editedByYou = edited.length > 0 && agentManaged;
198	  // Out of date stands the card down: it drops the accent, as a saved card
199	  // does, because it no longer vouches for the numbers under it.
200	  const outOfDate = estimate.status === 'stale' && !working && justChanged.length === 0 && !editedByYou;
201	  const saved = formatMoment(options.savedAt);
202	  const label = options.sent ? 'Saved sliced snapshot' : historical || outOfDate ? 'Earlier setup' : 'Setup summary';
203	  const state: ReactNode = historical
204	    ? options.sent ? 'Sliced & sent' : estimate.status === 'stale' ? 'Out of date'
205	      : saved ? <><span className="jp-icon jp-icon-clock" aria-hidden="true" />Saved {saved}</> : null
206	    : working ? 'Agent working' : justChanged.length > 0 ? 'Updated'
207	    : estimate.status === 'recomputing' ? 'Confirmed' : editedByYou ? 'Edited by you'
208	    : outOfDate ? 'Out of date' : estimate.status === 'none' && !estimate.sliced ? 'Not sliced' : 'Current';
209	  return { label, state, title, estimate, justChanged, edited, editedByYou, outOfDate, live: !historical && !outOfDate,
210	    fallback: false, noAgent: false };
211	}
