213	function Metrics({ estimate }: { estimate: EstimateView }) {
214	  return <div className="current-setup-metrics">
215	    {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
216	      <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
217	    {estimate.plate && <span className="current-setup-metric">
218	      <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
219	    {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
220	  </div>;
221	}
