223	function Attention({ findings }: { findings: Finding[] }) {
224	  const [open, setOpen] = useState(false);
225	  if (findings.length === 0) return null;
226	  const first = findings[0];
227	  const reviewable = findings.length > 1 || (first.facts ?? []).length > 0;
228	  const subject = findings.length > 1 ? plural(findings.length, 'finding', 'findings')
229	    : first.title.replace(/^(Last reported|Confirmed) | differs$/g, '');
230	  return <>
231	    <div className="current-setup-attention">
232	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />{first.title}</p>
233	      {first.detail && <p className="current-setup-line">{first.detail}</p>}
234	      {reviewable && <button type="button" className="current-setup-link" aria-expanded={open} onClick={() => setOpen(!open)}>
235	        Review {subject}</button>}
236	      {open && <ul className="current-setup-findings">{findings.map((finding, index) => <li key={index}>
237	        {findings.length > 1 && <strong>{finding.title}</strong>}
238	        {(finding.facts ?? []).map((fact) => <span key={fact}>{fact}</span>)}
239	      </li>)}</ul>}
240	    </div>
241	    <hr className="current-setup-divider" />
242	  </>;
243	}
