245	export function SetupCard({ context, working: busy = false, historical = false, savedAt, agentAvailable = true,
246	  changes, now = Date.now(), estimateBefore, sent, attention = [], onCompute, onUndo, onViewSetup }: SetupCardProps) {
247	  if (!context) return null;
248	  // A saved card is never working, whatever the active chat happens to be
249	  // doing.
250	  const working = busy && !historical;
251	  const ariaLabel = historical ? 'Earlier setup — saved with this conversation' : 'Current setup';
252	  const presentation = setupPresentation(context, { historical, working, agentAvailable, changes, now, sent, savedAt });
253	
254	  if (presentation.fallback) {
255	    const { estimate, title } = presentation;
256	    return <section className="current-setup current-setup--live" data-testid="current-setup" aria-label={ariaLabel}>
257	      <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
258	        {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
259	      {title && <h2 className="current-setup-title" title={title}>{title}</h2>}
260	      {presentation.noAgent ? <p className="current-setup-line">No agent configured · using the selected preset.</p>
261	        : estimate.metrics.length > 0 ? <Metrics estimate={estimate} />
262	        : <p className="current-setup-line">{estimate.description}</p>}
263	    </section>;
264	  }
265	
266	  const { estimate, justChanged, edited, editedByYou, outOfDate } = presentation;
267	  // The plan's headline in every state the card has: the state label and the
268	  // notices say how far the card can be trusted. With no plan pinned there is
269	  // no line at all.
270	  const headline = context.planHeadline.trim();
271	  const objects = overrideObjectCount(context);
272	  const presets = presetsLine(context, presentation.title);
273	
274	  const withheld = editedByYou && estimate.status === 'stale';
275	  const heading = withheld ? '' : estimate.heading ? estimate.heading : estimate.metrics.length === 0 ? ''
276	    : sent ? 'Saved pre-slice estimates' : working ? 'Last confirmed estimates' : '';
277	  const description = withheld ? (estimate.plate ? `Estimate unavailable for these edits · ${estimate.plate}`
278	    : 'Estimate unavailable for these edits') : estimate.description;
279	  const canCompute = !historical && !working && !!onCompute && estimate.status === 'none';
280	  // What the card adds for the minute a change is new. The settings the
281	  // agent changed are not listed: the thread's change rows under its turn
282	  // name them, and the setup page lists every difference. A project step is
283	  // named here, and it is the one thing Orca can undo: its undo takes the top
284	  // of its own stack, and a preset edit is not on it.
285	  const last = justChanged.at(-1);
286	  const step = !working && last?.kind === 'step' ? last : undefined;
287	  const undoable = !!onUndo && !!step && context.history.canUndo;
288	  const plate = context.plates.find((item) => item.active);
289	  const after = plate?.estimate;
290	  const estimateDelta = justChanged.length > 0 && estimateBefore && after && estimate.status === 'current' &&
291	    (estimateBefore.printTimeSeconds !== after.printTimeSeconds || estimateBefore.materialGrams !== after.materialGrams)
292	    ? `Estimate: ${estimatePair(estimateBefore)} → ${estimatePair(after)}` : '';
293	  const named = edited.slice(0, 2).map((change) => `${change.label} ${change.to || 'none'}`);
294	  const editedText = edited.length > 2 ? `${named.join(', ')} and ${plural(edited.length - 2, 'more setting', 'more settings')}`
295	    : named.join(' and ');
296	  const findings = [...deterministicAttention(context), ...attention];
297	
298	  return <section className={presentation.live ? 'current-setup current-setup--live' : 'current-setup'}
299	    data-testid="current-setup" aria-label={ariaLabel} aria-busy={working || undefined}>
300	    <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
301	      {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
302	    {presentation.title && <h2 className="current-setup-title" title={presentation.title}>{presentation.title}</h2>}
303	    {presets && <p className="current-setup-line current-setup-line--single" title={presets}>{presets}</p>}
304	    {headline && <p className="current-setup-strategy">{headline}</p>}
305	    {objects > 0 && <p className="current-setup-note">
306	      {plural(objects, 'object with overrides', 'objects with overrides')}</p>}
307	    {heading && <p className="current-setup-heading">{heading}</p>}
308	    {!withheld && estimate.metrics.length > 0 && <Metrics estimate={estimate} />}
309	    {description && <p className="current-setup-line">{description}</p>}
310	    {sent && estimate.metrics.length > 0 && <p className="current-setup-line">Actual time &amp; material unavailable.</p>}
311	    {canCompute && <button type="button" className="current-setup-link" onClick={onCompute}>Compute estimates</button>}
312	    <hr className="current-setup-divider" />
313	    {working && <><p className="current-setup-line">Agent is applying and evaluating changes…<br />
314	      Shown settings remain the last confirmed setup.</p><hr className="current-setup-divider" /></>}
315	    {!working && (step || estimateDelta) && <>
316	      {step && <p className="current-setup-line">{step.label || 'Object settings changed'}</p>}
317	      {estimateDelta && <p className="current-setup-line">{estimateDelta}</p>}
318	      {undoable && <button type="button" className="current-setup-link" onClick={() => onUndo!(step!.seq)}>Undo</button>}
319	      <hr className="current-setup-divider" />
320	    </>}
321	    {outOfDate && <><div className="current-setup-attention">
322	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />
323	        {historical ? 'These estimates were already out of date when saved.' : 'Estimates no longer match the current project.'}</p>
324	      {plate?.invalidatedBy && <p className="current-setup-line">{plate.invalidatedBy}</p>}
325	      {!historical && onCompute && <button type="button" className="current-setup-link" onClick={onCompute}>
326	        Refresh setup &amp; recompute</button>}
327	    </div><hr className="current-setup-divider" /></>}
328	    {editedByYou && <><p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
329	      <span>You set {editedText} outside the agent. Your current settings are preserved.</span></p>
330	      <hr className="current-setup-divider" /></>}
331	    <Attention findings={findings} />
332	    <button type="button" className="current-setup-link" onClick={onViewSetup}>View setup</button>
333	    {historical && <><hr className="current-setup-divider" />
334	      {sent && <p className="current-setup-sent">{[formatMoment(sent.at), sent.printer && `sent to ${sent.printer}`]
335	        .filter(Boolean).join(' · ')}</p>}
336	      <p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
337	        <span>{sent ? 'Saved snapshot.' : 'Saved with this chat.'} The canvas shows your current project.</span></p>
338	    </>}
339	  </section>;
340	}
