38	function readAsDataUrl(file: File): Promise<string> {
39	  return new Promise((resolve, reject) => {
40	    const reader = new FileReader();
41	    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
42	    reader.onerror = () => reject(reader.error ?? new Error('read failed'));
43	    reader.readAsDataURL(file);
