552	      );
553	    if (setupScreen === 'apiKey')
554	      return (
555	        <SetupApiKey
556	          setup={state.setup}
557	          onCheck={checkKey}
558	          onCancel={cancelCheck}
559	          onBack={() => {
560	            cancelCheck();
561	            setSetupScreen('chooser');
562	          }}
563	        />
564	      );
565	    return <AgentNotConfiguredPane onSetUp={openSetup} fileReports={fileReportNotes} />;
566	  };
567	
568	  if (printerPanel) {
569	    const session = state.session;
570	    const printerAction = (action: string) => client.send('printer_action', { action });
571	    // No tool closes the panel for the model: the person decides when they
572	    // are done, with Back or by opening the printer's own settings.
573	    const back = () => {
574	      const started = state.messages.some((message) => message.role === 'user') ||
575	        state.attachments.some((attachment) => attachment.state === 'staged') || printerDraft.current.trim() !== '';
576	      if (started) setConfirmPrinterClose(true);
577	      else printerAction('close');
578	    };
579	    return (
580	      // The whole panel takes a photo, not only the composer: a picture of
581	      // the printer is dropped where the person is looking.
582	      <div
583	        className="app app--printer app--printer-setup"
584	        onDragOver={(event) => event.preventDefault()}
585	        onDrop={(event) => {
586	          const files = Array.from(event.dataTransfer.files ?? []);
587	          if (files.length === 0) return;
588	          event.preventDefault();
589	          attachFiles(files, 'drop');
590	        }}
591	      >
592	        {errorNotice}
593	        <div className="chat-content">
594	          <header className="chat-header printer-header">
595	            <button type="button" className="panel-link-button panel-back-link" onClick={back}>
596	              <span className="jp-icon jp-icon-chevron-left" aria-hidden="true" /> Back
597	            </button>
598	            <button type="button" className="panel-link-button" onClick={() => printerAction(session?.printerName ? 'open_printer_settings' : 'manual_setup')}>
599	              {session?.printerName ? 'Open printer settings' : 'Browse the full printer list'}
600	            </button>
601	          </header>
602	          {confirmPrinterClose && (
603	            <Dialog title="Close this conversation?" onClose={() => setConfirmPrinterClose(false)}>
604	              <p>This conversation will be closed. You can't continue it at a later point. Are you sure?</p>
605	              <div className="chat-dialog-buttons">
606	                <button type="button" onClick={() => setConfirmPrinterClose(false)}>Cancel</button>
607	                <button type="button" className="danger decisive" onClick={() => { setConfirmPrinterClose(false); printerAction('close'); }}>
608	                  Close conversation
609	                </button>
610	              </div>
611	            </Dialog>
612	          )}
613	          {notConfigured ? (
614	            body()
615	          ) : (
616	            <MessageList
617	              messages={state.messages}
618	              attachments={state.attachments}
619	              streamingMessageId={state.streamingMessageId}
620	              onSend={sendMessage}
621	              replyDisabled={unavailable || streaming}
622	              toolActivities={state.toolActivities.filter((activity) => activity.tool === 'settings_apply_patch' ||
623	                activity.actionId === session?.credentialRequest?.actionId)}
624	              renderActivity={(activity) => activity.actionId !== session?.credentialRequest?.actionId ? undefined : (
625	                <PrinterCredentialForm request={session.credentialRequest} onConnect={connectPrinter} />
626	              )}
627	              builds={[]}
628	              exportedCopies={[]}
629	              physicalPrints={[]}
630	              changes={[]}
631	              printerBlocks={session?.blocks ?? []}
632	              onUndoAdd={(blockId) => client.send('printer_action', { action: 'undo_add', blockId })}
633	              onInstallPlugin={() => client.send('printer_action', { action: 'install_network_plugin' })}
634	              onRetry={(messageId) => client.send('retry_message', { messageId })}
635	              onToolCancel={sendToolCancel}
636	            />
637	          )}
638	          {!notConfigured && (
639	            <Composer
640	              disabled={unavailable}
641	              disabledReason={unavailable ? 'The Agent is not available' : undefined}
642	              placeholder={session ? placeholder(session) : undefined}
643	              photoButton
644	              streaming={streaming}
645	              attachments={stagedAttachments}
646	              onDraftChange={(text) => { printerDraft.current = text; }}
647	              draftDebounceMs={0}
648	              onSend={(text) => { printerDraft.current = ''; sendMessage(text); }}
649	              onStop={() => {
650	                if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
651	              }}
652	              onAttachFiles={attachFiles}
653	              onPickFiles={pickFiles}
654	              onRemoveAttachment={removeAttachment}
655	            />
656	          )}
657	        </div>
658	      </div>
659	    );
660	  }
661	
662	  if (embedded) {
663	    // No conversation header, chat list, composer, or external-tool banner --
664	    // just the setup sub-component itself, at whatever size its host gives it.
665	    return (
666	      <div className="app app--embedded">
667	        {errorNotice}
668	        <div className="chat-content">{body()}</div>
669	      </div>
670	    );
671	  }
672	
673	  return (
674	    <div className={state.navigation.focused ? 'app app--focused-chat' : 'app'}>
675	      {errorNotice}
676	      {view === 'list' && !state.navigation.focused && chatList}
677	      <div className="chat-content" hidden={view === 'list'}>
678	      {notConfigured && state.conversations.length === 1 && view !== 'setup' && view !== 'setupDetails' && !state.navigation.focused ? (
679	        <>
680	          <AgentNotConfiguredHeader onCollapse={collapseAgentPane} />
681	          {setupCard}
682	        </>
683	      ) : view === 'setupDetails' ? (
684	        <SetupPageHeader onBack={() => setView('chat')} onCollapse={collapseAgentPane} />
685	      ) : state.navigation.focused ? (
686	        <header className="chat-header printer-header">
687	          <button type="button" className="panel-link-button panel-back-link" aria-label={state.navigation.returnLabel ?? 'Back to Prepare'}
688	            onClick={() => { if (view === 'setup') closeSetup(); else returnToWorkspace(); }}><span className="jp-icon jp-icon-chevron-left" aria-hidden="true" /> Back</button>
689	          {view !== 'setup' && <button type="button" className="panel-link-button"
690	            onClick={() => client.send('shell_action', { action: 'open_filament_settings' })}>Open filament settings</button>}
691	          <AgentPaneToggle onCollapse={collapseAgentPane} />
692	        </header>
693	      ) : (
694	        <>
695	          <ChatHeader key={`header-${state.context?.sessionId}-${viewedId}`} title={viewedChat?.title || 'New chat'} busy={busy || pendingAction}
696	            onBack={() => { if (view === 'setup') closeSetup(); else { client.send('state_request', {}); setView('list'); } }}
697	            onCreate={createChat}
698	            onRename={(title) => client.send('rename_conversation', { conversationId: viewedId, title })}
699	            onDelete={() => { client.send('delete_conversation', { conversationId: viewedId }); setView('list'); }}
700	            onCollapse={collapseAgentPane} />
701	          {setupCard}
702	        </>
703	      )}
704	      {!notConfigured && connected && (
705	        <ConnectedBanner
706	          provider={connected.provider}
707	          warning={connected.warning}
708	          onDismiss={() => setConnected(null)}
709	        />
710	      )}
711	      {body()}
712	      {/* An earlier chat is read-only: its composer is an empty, disabled
713	          shell under the notice, with no draft and no attachments. */}
714	      {view === 'chat' && historical && <Composer
715	        key={`composer-historical-${viewedId}`}
716	        disabled
717	        disabledReason=""
718	        attachable={false}
719	        streaming={false}
720	        attachments={[]}
721	        notice={<>{blockedAlert}{projectUpdates}</>}
722	        onSend={() => {}}
723	        onStop={() => {}}
724	        onAttachFiles={() => {}}
725	        onRemoveAttachment={() => {}}
726	      />}
727	      {!historical && state.navigation.focused && notConfigured && blockedAlert}
728	      {!historical && !(state.navigation.focused && notConfigured) && <div hidden={view !== 'chat'}><Composer
729	        key={`composer-${state.context?.sessionId}-${viewedId}`}
730	        disabled={unavailable || state.projectChatBlocked}
731	        disabledReason={state.projectChatBlocked ? 'Project restoration needs recovery.' : notConfigured ? 'ask, or steer this chat…' : unavailable ? 'The Agent is not available' : undefined}
732	        attachable={!state.projectChatBlocked}
733	        notice={blockedAlert || undefined}
734	        placeholder={state.navigation.focused ? 'Ask about this filament or request a change…' : undefined}
735	        streaming={streaming}
736	        initialText={state.draft}
737	        attachments={stagedAttachments}
738	        onSend={sendMessage}
739	        onStop={() => {
740	          if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
741	        }}
742	        onAttachFiles={attachFiles}
743	        onPickFiles={pickFiles}
744	        onRemoveAttachment={removeAttachment}
745	        models={state.modelCatalog}
746	        chatModel={state.chatModel}
747	        onChooseModel={(choice) => client.send('set_chat_model', { ...choice })}
748	        onDraftChange={(text) => client.send('draft_update', { text })}
749	        draftDebounceMs={draftDebounceMs}
750	      /></div>}
751	      {confirmChatRestore && historical && <Dialog title="Restore this chat's project setup?"
752	        onClose={() => setConfirmChatRestore(false)}>
753	        <p>Restore “{viewedChat?.title || 'this chat'}” from {state.chatResume.savedAt || 'its saved checkpoint'}? Its earlier model and settings will replace the working version, with the matching intent and plan. Your current version will remain in history.</p>
754	        <div className="chat-dialog-buttons">
755	          <button type="button" onClick={() => setConfirmChatRestore(false)}>Cancel</button>
756	          <button type="button" className="primary" disabled={busy} onClick={() => {
757	            setConfirmChatRestore(false);
758	            client.send('restore_conversation', {
759	              conversationId: viewedId, activeConversationId: state.activeConversationId, docRevision: state.docRevision,
760	            });
761	          }}>Restore and resume</button>
762	        </div>
763	      </Dialog>}
764	      </div>
765	    </div>
766	  );
767	}
