13	  | 'hello'
14	  | 'state_request'
15	  | 'user_message'
16	  | 'stop_generation'
17	  | 'retry_message'
18	  | 'tool_cancel'
19	  | 'work_cancel'
20	  | 'create_conversation'
21	  | 'switch_conversation'
22	  | 'restore_conversation'
23	  | 'rename_conversation'
