30	  | 'mcp_catalog'
31	  | 'mcp_preview'
32	  | 'mcp_connect'
33	  | 'reveal_path'
34	  | 'pick_attachment'
35	  | 'set_chat_model'
36	  | 'printer_action'
37	  | 'printer_instructions'
38	  | 'printer_opening'
39	  | 'filament_instructions'
