44	export type HostMessageType =
45	  | 'hello_ack'
46	  | 'hello_reject'
47	  | 'state'
48	  | 'conversations_updated'
49	  | 'context'
50	  | 'appearance'
51	  | 'agent_status'
52	  | 'message_added'
53	  | 'assistant_started'
54	  | 'assistant_delta'
55	  | 'assistant_completed'
56	  | 'assistant_failed'
57	  | 'assistant_stopped'
58	  | 'tool_activity'
59	  | 'bridge_error'
60	  | 'attachment_updated'
61	  | 'setup_status'
62	  | 'mcp_catalog'
63	  | 'mcp_preview'
64	  | 'mcp_status'
65	  | 'change_added'
