71	
72	export interface Envelope<T = unknown> {
73	  protocol: string;
74	  version: number;
75	  id: string;
76	  type: string;
77	  correlationId?: string;
78	  sessionId?: string;
79	  revision?: number;
80	  payload: T;
81	}
82	
83	// 'note' is the host's own voice: a short factual line the native shell posts
84	// when it changes something the reader should see in the thread (a filament
85	// change, for example). It is never a turn -- no reply follows it, and the host never
86	// sends it to the model -- so it renders as a plain line, not a bubble.
87	export type MessageRole = 'user' | 'assistant' | 'note';
88	export type MessageStateName = 'complete' | 'streaming' | 'failed' | 'stopped';
89	export type AgentStatus = 'ready' | 'unavailable';
90	export type Appearance = 'light' | 'dark';
91	
92	export interface AgentErrorInfo {
93	  code: string;
94	  message: string;
95	  retryable: boolean;
96	}
97	
98	export interface WireMessage {
99	  id: string;
100	  role: MessageRole;
101	  state: MessageStateName;
102	  text: string;
103	  attempt: number;
104	  clientMessageId?: string;
105	  inReplyTo?: string;
106	  error?: AgentErrorInfo;
107	  attachments?: string[]; // sent attachment IDs, resolved against StatePayload.attachments
108	  swatch?: string; // notes: a colour, '#RRGGBB', that leads the line
109	  // Notes: what the app knows once a file the person brought in has loaded.
110	  // The model reads it; the page draws it only as a card, when the Agent
111	  // could not speak about it (fileReportCard).
112	  fileReport?: FileReport;
113	  fileReportCard?: boolean;
114	  // User messages sent from a print-issue bubble on the canvas: the issue,
115	  // its target and the freshness of the evidence, for the model. The page
116	  // draws the message's text and nothing from here.
117	  issueContext?: unknown;
118	}
