120	// Raw words shown or scheduled by Orca during opening, and the app's answer
121	// when there was a dialog. An empty answer belongs to a notification or error.
122	export interface OrcaMessage {
123	  source?: 'dialog' | 'notification' | 'error' | 'app';
124	  title: string;
125	  text: string;
126	  buttons: ('ok' | 'yes' | 'no' | 'cancel')[];
127	  answer: 'ok' | 'yes' | 'no' | 'cancel' | '';
128	  recognized?: false; // present only for a dialog the app did not know how to answer
129	}
