340	// The settings in force for the printable objects on one plate, read from
341	// OrcaSlicer on the GUI thread. Every value is the raw serialized config value
342	// under its stable key; wording is the card's job. `coverage` says how far a
343	// single value can be trusted: exact for the whole plate, mixed across
344	// objects, local when a modifier, part, height range or paint overrides it
345	// somewhere, unavailable when nothing printable defines it.
346	export interface AppliedSetupInfo {
347	  version: number;
348	  plateId: string;
349	  printableObjects: number;
350	  spiralMode: boolean;
351	  variableLayerHeight: boolean;
352	  // Names of the printable objects, in the order `object` indexes them.
353	  objects: string[];
354	  localOverrides: {
355	    object?: number;
356	    target: string;
357	    kind: string;
358	    // Empty for a customization with no setting of its own: paint, a blocker.
359	    key: string;
360	    value: string;
361	    // The setting's name and its value as the host's formatter writes it.
362	    // Absent for a customization OrcaSlicer defines no setting for.
363	    label?: string;
364	    display?: string;
365	  }[];
