738	export function isEnvelope(value: unknown): value is Envelope {
739	  if (typeof value !== 'object' || value === null) return false;
740	  const env = value as Record<string, unknown>;
741	  return (
742	    env.protocol === PROTOCOL_NAME &&
743	    typeof env.version === 'number' &&
744	    typeof env.id === 'string' &&
745	    typeof env.type === 'string'
746	  );
747	}
