1	// The setup page: everything the setup card counts but has no room for. The
2	// presets in full, each value that differs from them under the page and group
3	// it has in OrcaSlicer's settings, each object's own overrides, and each
4	// plate's estimate. It replaces the chat body, so the card in the chat never
5	// has to grow. Like the card, it presents facts the host read; a saved chat's
6	// page is that chat's saved summary, never today's project.
7	
8	import { ReactNode, useState } from 'react';
9	import { AppliedSetupInfo, ChangeInfo, PresetDeltaInfo, SetupIdentityInfo, WorkspaceContext } from '../bridge/protocol';
10	import { AgentPaneToggle } from './ChatNavigation';
11	import { formatGrams, formatPrintTime, setupPresentation } from './SetupCard';
12	
13	interface SetupPageProps {
14	  context: WorkspaceContext;
15	  historical?: boolean;
16	  working?: boolean;
17	  agentAvailable?: boolean;
18	  changes?: ChangeInfo[];
19	  now?: number;
20	  sent?: { at: string; printer: string };
21	  savedAt?: string;
22	}
23	
24	type LocalOverride = AppliedSetupInfo['localOverrides'][number];
25	
26	function Row({ label, children }: { label: string; children: ReactNode }) {
27	  return <div className="current-setup-row"><dt>{label}</dt><dd>{children}</dd></div>;
28	}
29	
30	function Presets({ context }: { context: WorkspaceContext }) {
31	  const identity = context.setupIdentity;
32	  const process = context.printer.process.trim();
33	  const filaments = identity?.filaments ?? [];
34	  if (!identity?.printer && !process && filaments.length === 0 && !identity?.plateType) return null;
35	  return <><hr className="current-setup-divider" /><section className="current-setup-section">
36	    <h3>Presets</h3>
37	    <dl className="current-setup-rows">
38	      {identity?.printer && <Row label="Printer">{identity.printer}</Row>}
39	      {process && <Row label="Process">{process}</Row>}
40	      {filaments.map((filament, index) => <Row key={index} label={filaments.length > 1 ? `Filament ${index + 1}` : 'Filament'}>
41	        {filament.preset || filament.material || 'Unavailable'}</Row>)}
42	      {identity?.plateType && <Row label="Build plate">{identity.plateType}</Row>}
43	    </dl>
44	  </section></>;
45	}
46	
47	// Consecutive runs that share a heading, in the order they first appear.
48	function runs<T>(items: T[], heading: (item: T) => string): [string, T[]][] {
49	  const groups = new Map<string, T[]>();
50	  for (const item of items) groups.set(heading(item), [...(groups.get(heading(item)) ?? []), item]);
51	  return [...groups];
52	}
53	
54	const PRESET_ORDER = ['process', 'filament', 'printer'];
55	
56	// One order whatever was edited last or by whom: process, filament, printer,
57	// and within a preset the host's, which is OrcaSlicer's own order of its
58	// settings, so its page and group runs read as its tabs do.
59	function PresetChanges({ deltas }: { deltas: PresetDeltaInfo[] }) {
60	  const rank = (delta: PresetDeltaInfo) => {
61	    const index = PRESET_ORDER.indexOf(delta.presetType ?? 'process');
62	    return index < 0 ? PRESET_ORDER.length : index;
63	  };
64	  const byPreset = runs([...deltas].sort((left, right) => rank(left) - rank(right)),
65	    (delta) => `${delta.presetType ?? ''}\u0000${delta.presetName ?? ''}`);
66	  return <><hr className="current-setup-divider" /><section className="current-setup-section">
67	    <h3>{deltas.length > 0 ? `Changed from presets · ${deltas.length}` : 'Changed from presets'}</h3>
68	    {deltas.length === 0 && <p className="current-setup-note">No changes from presets</p>}
69	    {byPreset.map(([preset, inPreset]) => <PresetGroup key={preset} name={inPreset[0].presetName ?? ''} deltas={inPreset} />)}
70	  </section></>;
71	}
72	
73	function PresetGroup({ name, deltas }: { name: string; deltas: PresetDeltaInfo[] }) {
74	  return <>
75	    {name && <p className="current-setup-object-name">{name}</p>}
76	    {runs(deltas, (delta) => [delta.page, delta.group].filter(Boolean).join(' · ')).map(([location, rows]) =>
77	      <Group key={location} heading={location}><DeltaRows deltas={rows} /></Group>)}
78	  </>;
79	}
80	
81	// One row per setting that differs: its name, and "preset → value" as the
82	// host formatted it, or the raw pair when the formatter had nothing to say.
83	// The name gives way on a narrow dock, with the setting's place in
84	// OrcaSlicer's tabs in its tooltip; the value is never cut.
85	function DeltaRows({ deltas }: { deltas: PresetDeltaInfo[] }) {
86	  return <dl className="current-setup-rows">{deltas.map((delta) => {
87	    const name = delta.label || delta.key;
88	    return <div className="current-setup-row current-setup-row--change" key={`${delta.presetType ?? ''}:${delta.key}`}>
89	      <dt title={[delta.page, delta.group, name].filter(Boolean).join(' · ')}>{name}</dt>
90	      <dd>{delta.display || `${delta.preset} → ${delta.value}`}</dd>
91	    </div>;
92	  })}</dl>;
93	}
94	
95	function Group({ heading, children }: { heading: string; children: ReactNode }) {
96	  return <>{heading && <p className="current-setup-group">{heading}</p>}{children}</>;
97	}
98	
99	const sentence = (text: string) => {
100	  const words = text.replace(/[_-]+/g, ' ').trim();
101	  return words.charAt(0).toUpperCase() + words.slice(1);
102	};
103	
104	// What an override is on, under its object's own name. A modifier is
105	// "bracket.stl / Mounting tabs", and the volume's name is enough; paint or a
106	// height range is on the object itself and is named by its kind.
107	function overrideHeading(local: LocalOverride): string {
108	  if (local.kind === 'object') return 'Whole object';
109	  const volume = local.target.indexOf(' / ');
110	  return volume < 0 ? sentence(local.kind) : `${local.target.slice(volume + 3)} · ${local.kind}`;
111	}
112	
113	function overrideValue(local: LocalOverride, identity: SetupIdentityInfo | null | undefined): string {
114	  // OrcaSlicer stores an object's filament as a slot number. This is the one
115	  // setting the page knows by its key: the number alone says nothing, and the
116	  // slot's preset is a fact the page already has.
117	  if (local.key === 'extruder') {
118	    const slot = Number(local.value);
119	    const filament = Number.isInteger(slot) && slot > 0 ? identity?.filaments[slot - 1] : undefined;
120	    if (filament) return `${slot} · ${filament.preset || filament.material}`;
121	  }
122	  return local.display || local.value;
123	}
124	
125	function ObjectOverrides({ object, name, locals, identity, open, onToggle }: { object: number; name: string;
126	  locals: LocalOverride[]; identity: SetupIdentityInfo | null | undefined; open: boolean; onToggle: () => void }) {
127	  if (locals.length === 0) return <div className="current-setup-object">
128	    <p className="current-setup-object-name">{name}</p>
129	    <p className="current-setup-note">Uses plate settings</p>
130	  </div>;
131	  const targets = runs(locals, overrideHeading);
132	  return <>
133	    <button type="button" className="current-setup-disclosure" aria-expanded={open} aria-controls={`setup-object-${object}`}
134	      onClick={onToggle}>
135	      <span className={`jp-icon jp-icon-chevron-${open ? 'down' : 'right'}`} aria-hidden="true" />
136	      {name} · {locals.length} {locals.length === 1 ? 'override' : 'overrides'}
137	    </button>
138	    {open && <div className="current-setup-object-rows" id={`setup-object-${object}`}>
139	      {targets.map(([heading, rows]) => {
140	        // Paint, a blocker, a variable-height profile: a customization with
141	        // no value to quote is named by its heading alone.
142	        const valued = rows.filter((local) => local.key && (local.display || local.value));
143	        return <Group key={heading} heading={heading}>
144	          {valued.length > 0 && <dl className="current-setup-rows">{valued.map((local, index) => {
145	            // A customization OrcaSlicer has no setting name for shows its key.
146	            const name = local.label || sentence(local.key);
147	            return <div className="current-setup-row current-setup-row--change" key={`${local.key}-${index}`}>
148	              <dt title={name}>{name}</dt><dd>{overrideValue(local, identity)}</dd>
149	            </div>;
150	          })}</dl>}
151	        </Group>;
152	      })}
153	    </div>}
154	  </>;
155	}
156	
157	function Objects({ context }: { context: WorkspaceContext }) {
158	  const names = context.appliedSetup?.objects ?? [];
159	  const locals = context.appliedSetup?.localOverrides ?? [];
160	  const of = (object: number) => locals.filter((local) => local.object === object);
161	  // The first object that has overrides starts open: the page was opened to
162	  // read them.
163	  const [open, setOpen] = useState<Set<number>>(() => new Set(names.map((_, object) => object)
164	    .filter((object) => of(object).length > 0).slice(0, 1)));
165	  if (names.length === 0) return null;
166	  const plate = context.plates.find((item) => item.active)?.name;
167	  return <><hr className="current-setup-divider" /><section className="current-setup-section">
168	    <h3>{plate ? `Objects on ${plate}` : 'Objects'} · {names.length}</h3>
169	    {names.map((name, object) => <ObjectOverrides key={object} object={object} name={name} locals={of(object)}
170	      identity={context.setupIdentity} open={open.has(object)} onToggle={() => setOpen((before) => {
171	        const next = new Set(before);
172	        if (!next.delete(object)) next.add(object);
173	        return next;
174	      })} />)}
175	  </section></>;
176	}
177	
178	function plateFacts(context: WorkspaceContext, index: number): string {
179	  const plate = context.plates[index];
180	  const facts: string[] = [];
181	  const estimate = plate.sliced ? plate.estimate : null;
182	  if (estimate && (estimate.timeAvailable ?? estimate.printTimeSeconds > 0)) facts.push(formatPrintTime(estimate.printTimeSeconds));
183	  if (estimate && (estimate.materialAvailable ?? estimate.materialGrams > 0)) facts.push(formatGrams(estimate.materialGrams));
184	  if (facts.length === 0) facts.push(plate.sliced ? 'Estimate unavailable' : 'Not sliced');
185	  // Spiral vase is the plate's own switch, not a difference from a preset,
186	  // and the host reads it for the plate on show.
187	  if (plate.active && context.appliedSetup?.spiralMode) facts.push('Spiral vase');
188	  return facts.join(' · ');
189	}
190	
191	function Plates({ context }: { context: WorkspaceContext }) {
192	  if (context.plates.length === 0) return null;
193	  return <><hr className="current-setup-divider" /><section className="current-setup-section">
194	    <h3>Plates</h3>
195	    <dl className="current-setup-rows">{context.plates.map((plate, index) =>
196	      <Row key={plate.id} label={plate.active && context.plates.length > 1 ? `${plate.name} · shown` : plate.name}>
197	        {plateFacts(context, index)}</Row>)}</dl>
198	  </section></>;
199	}
200	
201	// The page's own header bar: the way back to the chat, and the same control
202	// the chat's header has for putting the whole panel away. Back takes the focus
203	// the "View setup" link had, so the keyboard is never left on nothing.
204	export function SetupPageHeader({ onBack, onCollapse }: { onBack: () => void; onCollapse: () => void }) {
205	  return <header className="chat-header current-setup-page-header">
206	    <button type="button" className="panel-link-button panel-back-link" autoFocus onClick={onBack}>
207	      <span className="jp-icon jp-icon-chevron-left" aria-hidden="true" /> Back
208	    </button>
209	    <AgentPaneToggle onCollapse={onCollapse} />
210	  </header>;
211	}
212	
213	export function SetupPage({ context, historical, working, agentAvailable, changes, now, sent, savedAt }: SetupPageProps) {
214	  const presentation = setupPresentation(context, { historical, working, agentAvailable, changes, now, sent, savedAt });
215	  return <main className="current-setup-page" data-testid="current-setup-page">
216	    <section className={presentation.live ? 'current-setup current-setup--live' : 'current-setup'}
217	      aria-label={historical ? 'Earlier setup — saved with this conversation' : 'Current setup'}>
218	      <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
219	        {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
220	      {presentation.title && <h2 className="current-setup-title" title={presentation.title}>{presentation.title}</h2>}
221	      <Presets context={context} />
222	      <PresetChanges deltas={context.presetDeltas} />
223	      <Objects context={context} />
224	      <Plates context={context} />
225	    </section>
226	  </main>;
227	}
