/* The setup page's header: Back at one end, the panel's own toggle at the
   other, where the chat header has it. */
.current-setup-page-header {
  justify-content: space-between;
}

/* The setup page's scrolling body, in place of the thread: the pinned
   band's own padding and surface, and the height the thread had. */
.current-setup-page {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 12px;
  background: var(--surface-canvas);
}

/* Which settings-tab page and group, or which part of an object, a run of
   rows belongs to. */
.current-setup-group {
  padding-top: 4px;
  font: var(--font-metadata-bold);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

/* A setting's row keeps to one line where it can: its name gives way, and
   the value is never cut. The whole name is in the tooltip. */
.current-setup-row--change dt {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

